import os,json,subprocess,stat,time
from pathlib import Path
repo_names=['telegram-robot-leads','sms-man','insolvencia','free-numbers','iptvpn-bot','lowcost-europa','pink-iptv','MotionCam-iOS','IOS-16-USB-4k','IOS-15-USB','VCAM-PRO','VPS','fadego','Project-leader','Orquestra-de-agentes','Project-leader-codex','Codex','Criativos-anuncios','Engenheira-reversa','Qwen','dopamine','skill-universal']
root=Path('/srv/projects')
def cmd(argv,timeout=30):
 try:
  x=subprocess.run(argv,capture_output=True,text=True,timeout=timeout)
  return {'code':x.returncode,'out':x.stdout.strip()[-2600:]}
 except Exception as e:return {'error':type(e).__name__}
def meta(p):
 try:
  x=p.lstat();typ='symlink' if stat.S_ISLNK(x.st_mode) else 'directory' if stat.S_ISDIR(x.st_mode) else 'file'
  return {'type':typ,'owner_uid':x.st_uid,'link':os.readlink(p) if typ=='symlink' else None,'mode':oct(x.st_mode&0o777)}
 except OSError:return None
def disk(p):
 if not p.exists() or p.is_symlink():return None
 x=cmd(['/usr/bin/du','-sk','--one-file-system',str(p)],100)
 try:return int(x['out'].split()[0])*1024
 except Exception:return None
report={'audit':'vps-github-exact-repo-project-roots','date_utc':time.strftime('%FT%TZ',time.gmtime()),'mode':'read-only','root_exists':root.is_dir(),'expected_repos':repo_names,'root_disk_free_bytes':os.statvfs(str(root)).f_bavail*os.statvfs(str(root)).f_frsize}
report['projects']=[]
if root.is_dir():
 for p in sorted(root.iterdir(),key=lambda x:x.name.lower()):
  m=meta(p);m.update({'name':p.name,'match':p.name in repo_names,'casefold_matches':[n for n in repo_names if n.lower()==p.name.lower()],'size_bytes':disk(p)})
  if p.is_dir():
   try:m['children']=[x.name for x in list(sorted(p.iterdir(),key=lambda x:x.name))[:32] if x.name not in ('node_modules','.git','.venv','venv','dist')]
   except OSError:m['children']=[]
   git=p/'.git'
   if git.exists() and not git.is_symlink() and git.is_dir():
    x=cmd(['/usr/bin/git','-C',str(p),'rev-parse','--short=12','HEAD'],8)
    m['git_head']=x.get('out','') if x.get('code')==0 else None
  report['projects'].append(m)
report['known_repo_present']={name:(root/name).is_dir() and not (root/name).is_symlink() for name in repo_names}
report['top_level']={}
for key in ['/srv','/opt','/usr/local','/home/ubuntu','/root','/var/lib','/var/www','/var/log','/tmp']:
 p=Path(key)
 if p.is_dir():
  children=[]
  for child in sorted(p.iterdir(),key=lambda a:a.name)[:75]:
   if child.name in ('.ssh','.gnupg','.config','.local','.npm','.cache','node_modules'):continue
   children.append({'name':child.name,**(meta(child) or {})})
  report['top_level'][key]=children
report['disk_usage']={x:disk(Path(x)) for x in ['/srv/projects','/opt','/usr/local','/home/ubuntu','/root','/var/log','/tmp']}
report['disk_fs']=cmd(['/bin/df','-B1','/srv/projects','/','/opt'],12)
print(json.dumps(report,ensure_ascii=True,sort_keys=True))
